#include <stdio.h>

static int divide(double a, double b, int *ok) {
    if (b == 0) { *ok = 0; return 0; }
    *ok = 1; return (int)(a / b);
}

int main(void) {
    int ok;
    divide(10, 0, &ok);
    if (!ok) puts("Error: division by zero");
    return 0;
}

